¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â TC-EVAL-007. Stored on both final rows once both exist (no dedicated "final grade" column elsewhere). */
    private function maybeComputeCombinedGrade(int $internshipId): void
    {
        $companyTemplate = $this->getTemplateByType('company_final');
        $teacherTemplate = $this->getTemplateByType('teacher_final');
        if ($companyTemplate === null || $teacherTemplate === null) {
            return;
        }
        $companyEval = $this->findEvaluation($internshipId, $companyTemplate['id'], null);
        $teacherEval = $this->findEvaluation($internshipId, $teacherTemplate['id'], null);
        if ($companyEval === null || $teacherEval === null || $companyEval['status'] !== 'submitted' || $teacherEval['status'] !== 'submitted') {
            return;
        }

        // Keep the "both final evaluations exist" hook here for future weighted-grade support.
        $this->client->restGet('evaluations', 'id=eq.' . $companyEval['id'] . '&select=total_score');
