Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â RULE-EVAL-06: hidden from the student unless settings.score_visible_to_student. */
    public function getHistoryForInternship(int $internshipId, bool $isStudentViewer): array
    {
        if ($isStudentViewer && !$this->settings->getBool('score_visible_to_student', true)) {
            return [];
        }
        $rows = $this->client->restGet(
            'evaluations',
            'internship_id=eq.' . $internshipId . '&status=eq.submitted&select=id,template_id,week_number,total_score&order=created_at.desc'
        );
        $templates = $this->client->restGet('evaluation_templates', 'select=id,evaluator_type');
        $typeById = array_column($templates, 'evaluator_type', 'id');
        return array_map(static fn (array $r) => [
            'id' => $r['id'],
            'template' => $typeById[$r['template_id']] ?? '-',
            'week_number' => $r['week_number'],
            'total_score' => (float) $r['total_score'],
            'grade' => null,
        ], $rows);
    }

    /**
     * RULE-EVAL-05 exception path. PIN verification itself is Phase 10 scope (not built yet);
     * this is gated purely by the caller being role=super_admin (route-level AuthGuard), which
     * is the same enforcement level every other admin-only action in this codebase uses so far.
     * Every call is written to audit_logs regardless of outcome intent (old/new value).
     */
    public function adminOverrideScores(int $evaluationId, array $scores, string $adminUserId): void
    {
        $rows = $this->client->restGet('evaluations', 'id=eq.' . $evaluationId . '&select=id,template_id,status');
        if (!isset($rows[0])) {
            throw new AuthException('VALIDATION_ERROR', 'ไม่พบแบบประเมินที่ต้องการแก้ไข');
        }

        $templateId = (int) $rows[0]['template_id'];
        $criteria = $this->client->restGet('evaluation_criteria', 'template_id=eq.' . $templateId . '&select=id,criteria_name,max_score&order=sort_order.asc');
        $criteriaById = [];
        foreach ($criteria as $criterion) {
            $criteriaById[(int) $criterion['id']] = $criterion;
        }

        $oldScores = $this->client->restGet('evaluation_scores', 'evaluation_id=eq.' . $evaluationId . '&select=criteria_id,score');
        $newRows = [];
        $total = 0.0;
        foreach ($scores as $criteriaIdRaw => $scoreRaw) {
            $criteriaId = (int) $criteriaIdRaw;
            if (!isset($criteriaById[$criteriaId])) {
                throw new AuthException('VALIDATION_ERROR', 'พบหัวข้อประเมินที่ไม่มีอยู่ในระบบ');
            }
            if (!is_numeric($scoreRaw)) {
                throw new AuthException('VALIDATION_ERROR', 'คะแนนที่กรอกไม่ถูกต้อง');
            }

            $score = round((float) $scoreRaw, 2);
            $maxScore = (float) $criteriaById[$criteriaId]['max_score'];
            if ($score < 0 || $score > $maxScore) {
                throw new AuthException('VALIDATION_ERROR', 'คะแนนของหัวข้อ "' . $criteriaById[$criteriaId]['criteria_name'] . '" ต้องอยู่ระหว่าง 0 ถึง ' . $maxScore);
            }

            $total += $score;
            $newRows[] = ['evaluation_id' => $evaluationId, 'criteria_id' => $criteriaId, 'score' => $score];
        }

        $this->client->restDelete('evaluation_scores', 'evaluation_id=eq.' . $evaluationId);
        $this->client->restInsert('evaluation_scores', $newRows);
        $this->client->restUpdate('evaluations', 'id=eq.' . $evaluationId, ['total_score' => round($total, 2)]);

        (new AuditLogger($this->client))->log(
            $adminUserId,
            'super_admin',
            'override_score',
            'evaluations',
            'evaluations',
            $evaluationId,
            ['scores' => $oldScores],
            ['scores' => $newRows]
        );
    }
}
